import React, { useEffect, useState } from 'react'
import { Link, useHistory } from 'react-router-dom'
import { Row, Col, Container, Image, Card } from 'react-bootstrap'
import { useDispatch, useSelector } from 'react-redux'

import { getProductDetails } from '../actions/productActions'
import CreateCardComponent from '../components/CreateCardComponent'
import ChargeCardComponent from '../components/ChargeCardComponent'
import Message from '../components/Message'
import { Spinner } from 'react-bootstrap'
import { savedCardsList } from '../actions/cardActions'
import UserAddressComponent from '../components/UserAddressComponent'
import { checkTokenValidation, logout } from '../actions/userActions'
import { CHARGE_CARD_RESET } from '../constants/index'

import './CheckoutPage.css'


const CheckoutPage = ({ match }) => {

    const history = useHistory()
    const dispatch = useDispatch()

    const [addressSelected, setAddressSelected] = useState(false)
    const [selectedAddressId, setSelectedAddressId] = useState(0)


    // ==============================
    // ADDRESS
    // ==============================

    const handleAddressId = (id) => {

        if (id) {
            setAddressSelected(true)
        }

        setSelectedAddressId(id)
    }


    // ==============================
    // TOKEN
    // ==============================

    const checkTokenValidationReducer = useSelector(
        state => state.checkTokenValidationReducer
    )

    const {
        error: tokenError
    } = checkTokenValidationReducer


    // ==============================
    // PRODUCT
    // ==============================

    const productDetailsReducer = useSelector(
        state => state.productDetailsReducer
    )

    const {
        loading,
        error,
        product
    } = productDetailsReducer


    // ==============================
    // CREATE CARD
    // ==============================

    const createCardReducer = useSelector(
        state => state.createCardReducer
    )

    const {
        error: cardCreationError,
        success,
        loading: cardCreationLoading
    } = createCardReducer


    // ==============================
    // LOGIN
    // ==============================

    const userLoginReducer = useSelector(
        state => state.userLoginReducer
    )

    const {
        userInfo
    } = userLoginReducer


    // ==============================
    // SAVED CARDS
    // ==============================

    const savedCardsListReducer = useSelector(
        state => state.savedCardsListReducer
    )

    const {
        stripeCards
    } = savedCardsListReducer


    // ==============================
    // LOAD CHECKOUT
    // ==============================

    useEffect(() => {

        if (!userInfo) {

            history.push('/login')

        } else {

            dispatch(checkTokenValidation())

            dispatch(
                getProductDetails(match.params.id)
            )

            dispatch(savedCardsList())

            dispatch({
                type: CHARGE_CARD_RESET
            })
        }

    }, [
        dispatch,
        match.params.id,
        history,
        success,
        userInfo
    ])


    // ==============================
    // TOKEN EXPIRED
    // ==============================

    if (
        userInfo &&
        tokenError === 'Request failed with status code 401'
    ) {

        alert('Session expired, please login again.')

        dispatch(logout())

        history.push('/login')

        window.location.reload()
    }


    return (

        <div className="checkout-page">

            <Container className="checkout-container">


                {/* ==============================
                    PAGE HEADER
                ============================== */}

                <div className="checkout-header">

                    <button
                        className="checkout-back-btn"
                        onClick={() => history.goBack()}
                    >
                        ← Back
                    </button>

                    <div>

                        <span className="checkout-label">
                            SECURE CHECKOUT
                        </span>

                        <h1>
                            Complete Your Order
                        </h1>

                        <p>
                            Review your product and payment details
                        </p>

                    </div>

                </div>


                {/* ==============================
                    ERROR
                ============================== */}

                {cardCreationError && (

                    <div className="checkout-message">

                        <Message variant="danger">
                            {cardCreationError}
                        </Message>

                    </div>

                )}


                {error && (

                    <div className="checkout-message">

                        <Message variant="danger">
                            {error}
                        </Message>

                    </div>

                )}


                {/* ==============================
                    LOADING
                ============================== */}

                {loading && (

                    <div className="checkout-loading">

                        <Spinner animation="border" />

                        <span>
                            Getting Checkout Information...
                        </span>

                    </div>

                )}


                {!loading && cardCreationLoading && (

                    <div className="checkout-loading">

                        <Spinner animation="border" />

                        <span>
                            Checking your card...
                        </span>

                    </div>

                )}


                {/* ==============================
                    MAIN CHECKOUT
                ============================== */}

                {!loading && !error && product && (

                    <Row className="checkout-row">


                        {/* ==============================
                            LEFT SECTION
                        ============================== */}

                        <Col lg={7} md={12}>


                            {/* PRODUCT SUMMARY */}

                            <Card className="checkout-card product-summary-card">

                                <Card.Body>

                                    <div className="section-heading">

                                        <div className="section-icon">
                                            🛍️
                                        </div>

                                        <div>

                                            <h2>
                                                Checkout Summary
                                            </h2>

                                            <p>
                                                Your selected product
                                            </p>

                                        </div>

                                    </div>


                                    <div className="product-summary">


                                        {/* PRODUCT IMAGE */}

                                        <div className="checkout-product-image-box">

                                            <Image
                                                src={
                                                    product.image &&
                                                    (
                                                        product.image.startsWith('http')
                                                            ? product.image
                                                            : 'http://127.0.0.1:8000/images/' +
                                                              String(product.image)
                                                                .replace('/images/', '')
                                                                .replace('images/', '')
                                                    )
                                                }
                                                alt={product.name}
                                                className="checkout-product-image"
                                                onError={(e) => {
                                                    e.target.style.display = 'none'
                                                }}
                                            />

                                        </div>


                                        {/* PRODUCT DETAILS */}

                                        <div className="checkout-product-info">

                                            <span className="product-small-label">
                                                PRODUCT
                                            </span>

                                            <h3 className="checkout-product-name">
                                                {product.name}
                                            </h3>

                                            <p className="checkout-product-description">
                                                {product.description}
                                            </p>

                                            <div className="checkout-product-bottom">

                                                <span className="checkout-price">
                                                    ₹ {product.price}
                                                </span>

                                                {product.stock ? (

                                                    <span className="checkout-stock">
                                                        ✓ In Stock
                                                    </span>

                                                ) : (

                                                    <span className="checkout-out-stock">
                                                        ✕ Out Of Stock
                                                    </span>

                                                )}

                                            </div>

                                        </div>

                                    </div>

                                </Card.Body>

                            </Card>


                            {/* BILLING ADDRESS */}

                            <Card className="checkout-card address-card">

                                <Card.Body>

                                    <div className="section-heading">

                                        <div className="section-icon">
                                            📍
                                        </div>

                                        <div className="address-heading-content">

                                            <h2>
                                                Billing Address
                                            </h2>

                                            <p>
                                                Select your delivery and billing address
                                            </p>

                                        </div>

                                        <Link
                                            className="edit-address-btn"
                                            to="/all-addresses/"
                                        >
                                            ✏ Edit / Add
                                        </Link>

                                    </div>


                                    <div className="address-component-wrapper">

                                        <UserAddressComponent
                                            handleAddressId={
                                                handleAddressId
                                            }
                                        />

                                    </div>

                                </Card.Body>

                            </Card>

                        </Col>


                        {/* ==============================
                            RIGHT PAYMENT SECTION
                        ============================== */}

                        <Col lg={5} md={12}>


                            <Card className="checkout-card payment-card">

                                <Card.Body>

                                    <div className="section-heading">

                                        <div className="section-icon payment-icon">
                                            💳
                                        </div>

                                        <div>

                                            <h2>
                                                Payment
                                            </h2>

                                            <p>
                                                Secure payment processing
                                            </p>

                                        </div>

                                    </div>


                                    {/* ORDER TOTAL */}

                                    <div className="order-total-box">

                                        <div>
                                            <span>
                                                Product
                                            </span>

                                            <strong>
                                                {product.name}
                                            </strong>
                                        </div>


                                        <div>
                                            <span>
                                                Total
                                            </span>

                                            <strong className="total-price">
                                                ₹ {product.price}
                                            </strong>
                                        </div>

                                    </div>


                                    {/* PAYMENT COMPONENT */}

                                    <div className="payment-component">

                                        {success ? (

                                            <ChargeCardComponent
                                                selectedAddressId={
                                                    selectedAddressId
                                                }
                                                addressSelected={
                                                    addressSelected
                                                }
                                                product={product}
                                            />

                                        ) : (

                                            <CreateCardComponent
                                                addressSelected={
                                                    addressSelected
                                                }
                                                stripeCards={
                                                    stripeCards
                                                }
                                            />

                                        )}

                                    </div>


                                    {/* SECURITY */}

                                    <div className="secure-payment">

                                        <span className="lock-icon">
                                            🔒
                                        </span>

                                        <div>

                                            <strong>
                                                Secure Payment
                                            </strong>

                                            <p>
                                                Your payment information is protected
                                            </p>

                                        </div>

                                    </div>

                                </Card.Body>

                            </Card>

                        </Col>

                    </Row>

                )}

            </Container>

        </div>
    )
}


export default CheckoutPage
